(() => {
  const plans = { single: [499, "Single guest post"], m5: [999, "Membership · 5 articles for 1 year"], m10: [1499, "Membership · 10 articles for 1 year"], m50: [2999, "Membership · 50 articles for 1 year"], m100: [4999, "Membership · 100 articles for 1 year"] };
  const $ = (s) => document.querySelector(s);
  const sel = $("#wfu-plan");
  const inr = (n) => "₹" + n.toLocaleString("en-IN");
  const setPlan = (key, scroll) => {
    sel.value = key;
    document.querySelectorAll("[data-pick]").forEach((b) => b.classList.contains("wfu-card") && b.setAttribute("aria-pressed", String(b.dataset.pick === key)));
    $(".wfu-single").dataset.selected = String(key === "single");
    $("[data-total]").textContent = inr(plans[key][0]);
    $("[data-total-note]").textContent = plans[key][1];
    if (scroll) $("#submit").scrollIntoView({ behavior: "smooth", block: "start" });
  };
  document.querySelectorAll("[data-pick]").forEach((b) => b.addEventListener("click", () => setPlan(b.dataset.pick, true)));
  sel.addEventListener("change", () => setPlan(sel.value, false));
  const slugify = (t) => t.toLowerCase().normalize("NFKD").replace(/[^\w\s-]/g, "").trim().replace(/[\s_]+/g, "-").replace(/-+/g, "-").slice(0, 80);
  let slugEdited = false;
  const slug = $("#wfu-slug"), title = $("#wfu-title"), mt = $("#wfu-mtitle"), md = $("#wfu-mdesc");
  const serp = () => {
    $("[data-serp-url]").textContent = "https://www.knewspaper.in/post/" + (slug.value || "your-slug");
    $("[data-serp-title]").textContent = (mt.value || title.value || "Your SEO title appears here") + " | Knewspaper";
    $("[data-serp-desc]").textContent = md.value || "Your meta description appears here.";
  };
  title.addEventListener("input", () => { if (!slugEdited) slug.value = slugify(title.value); serp(); });
  slug.addEventListener("input", () => { slugEdited = true; slug.value = slugify(slug.value); serp(); });
  document.querySelectorAll("[data-count]").forEach((c) => {
    const el = document.getElementById(c.dataset.count), max = +c.dataset.max;
    el.addEventListener("input", () => { c.textContent = el.value.length + "/" + max; c.toggleAttribute("data-over", el.value.length > max); serp(); });
  });
  $("#wfu-body").addEventListener("input", (e) => { const n = e.target.value.trim().split(/\s+/).filter(Boolean).length; $("[data-words]").textContent = n + " words"; });
  $("#wfu-image").addEventListener("change", (e) => {
    const f = e.target.files[0]; if (!f) return;
    const drop = $("[data-drop]"); drop.replaceChildren();
    const img = new Image(); img.alt = ""; img.src = URL.createObjectURL(f); drop.append(img);
  });
  document.querySelectorAll("[data-demo]").forEach((a) => a.addEventListener("click", (e) => { e.preventDefault(); const s = $(".form-status"); s.dataset.kind = "ok"; s.textContent = "Sample only: member login isn't connected yet."; }));
  $(".wfu-form").addEventListener("submit", (e) => { e.preventDefault(); const s = $(".form-status"); s.dataset.kind = "ok"; s.textContent = "Sample only: payment isn't connected yet. On the live page this goes to secure checkout for " + $("[data-total]").textContent + "."; });
  setPlan("single", false);
})();
